/* --- Zona urbana / rural por municipio (plantilla territorial) --- */
INSERT INTO `zona` (`municipio_id`, `tipo`, `codigo`, `nombre`, `estado_id`) SELECT m.`id`, 'urbana', 'U', SUBSTRING(CONCAT('Zona urbana — ', m.`nombre`), 1, 200), 1 FROM `municipio` m JOIN `departamento` d ON d.`id` = m.`departamento_id` AND d.`pais_id` = @pais_co_id ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);

INSERT INTO `zona` (`municipio_id`, `tipo`, `codigo`, `nombre`, `estado_id`) SELECT m.`id`, 'rural', 'R', SUBSTRING(CONCAT('Zona rural — ', m.`nombre`), 1, 200), 1 FROM `municipio` m JOIN `departamento` d ON d.`id` = m.`departamento_id` AND d.`pais_id` = @pais_co_id ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);

/* --- Comunas oficiales Medellín (05001), zona urbana --- */
INSERT INTO `comuna` (`zona_id`, `codigo`, `nombre`, `estado_id`) SELECT z.`id`, v.`codigo`, v.`nombre`, 1 FROM `zona` z JOIN `municipio` m ON m.`id` = z.`municipio_id` CROSS JOIN (SELECT '01' AS codigo, 'Popular' AS nombre UNION ALL SELECT '02' AS codigo, 'Santa Cruz' AS nombre UNION ALL SELECT '03' AS codigo, 'Manrique' AS nombre UNION ALL SELECT '04' AS codigo, 'Aranjuez' AS nombre UNION ALL SELECT '05' AS codigo, 'Castilla' AS nombre UNION ALL SELECT '06' AS codigo, 'Doce de Octubre' AS nombre UNION ALL SELECT '07' AS codigo, 'Robledo' AS nombre UNION ALL SELECT '08' AS codigo, 'Villa Hermosa' AS nombre UNION ALL SELECT '09' AS codigo, 'Buenos Aires' AS nombre UNION ALL SELECT '10' AS codigo, 'La Candelaria' AS nombre UNION ALL SELECT '11' AS codigo, 'Laureles — Estadio' AS nombre UNION ALL SELECT '12' AS codigo, 'La América' AS nombre UNION ALL SELECT '13' AS codigo, 'San Javier' AS nombre UNION ALL SELECT '14' AS codigo, 'El Poblado' AS nombre UNION ALL SELECT '15' AS codigo, 'Guayabal' AS nombre UNION ALL SELECT '16' AS codigo, 'Belén' AS nombre) AS v WHERE m.`codigo` = '05001' AND z.`tipo` = 'urbana' ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);

/* --- Localidades Bogotá D.C. (11001) como comunas, zona urbana --- */
INSERT INTO `comuna` (`zona_id`, `codigo`, `nombre`, `estado_id`) SELECT z.`id`, v.`codigo`, v.`nombre`, 1 FROM `zona` z JOIN `municipio` m ON m.`id` = z.`municipio_id` CROSS JOIN (SELECT '01' AS codigo, 'Usaquén' AS nombre UNION ALL SELECT '02' AS codigo, 'Chapinero' AS nombre UNION ALL SELECT '03' AS codigo, 'Santa Fe' AS nombre UNION ALL SELECT '04' AS codigo, 'San Cristóbal' AS nombre UNION ALL SELECT '05' AS codigo, 'Usme' AS nombre UNION ALL SELECT '06' AS codigo, 'Tunjuelito' AS nombre UNION ALL SELECT '07' AS codigo, 'Bosa' AS nombre UNION ALL SELECT '08' AS codigo, 'Kennedy' AS nombre UNION ALL SELECT '09' AS codigo, 'Fontibón' AS nombre UNION ALL SELECT '10' AS codigo, 'Engativá' AS nombre UNION ALL SELECT '11' AS codigo, 'Suba' AS nombre UNION ALL SELECT '12' AS codigo, 'Barrios Unidos' AS nombre UNION ALL SELECT '13' AS codigo, 'Teusaquillo' AS nombre UNION ALL SELECT '14' AS codigo, 'Los Mártires' AS nombre UNION ALL SELECT '15' AS codigo, 'Antonio Nariño' AS nombre UNION ALL SELECT '16' AS codigo, 'Puente Aranda' AS nombre UNION ALL SELECT '17' AS codigo, 'La Candelaria' AS nombre UNION ALL SELECT '18' AS codigo, 'Rafael Uribe Uribe' AS nombre UNION ALL SELECT '19' AS codigo, 'Ciudad Bolívar' AS nombre UNION ALL SELECT '20' AS codigo, 'Sumapaz' AS nombre) AS v WHERE m.`codigo` = '11001' AND z.`tipo` = 'urbana' ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);

/* --- Barrios ejemplo (Medellín, comuna Popular) --- */
INSERT INTO `barrio` (`comuna_id`, `codigo`, `nombre`, `estado_id`) SELECT c.`id`, v.`codigo`, v.`nombre`, 1 FROM `comuna` c JOIN `zona` z ON z.`id` = c.`zona_id` JOIN `municipio` m ON m.`id` = z.`municipio_id` CROSS JOIN (SELECT '001' AS codigo, 'Popular' AS nombre UNION ALL SELECT '002', 'Villa del Socorro' UNION ALL SELECT '003', 'San Pablo') AS v WHERE m.`codigo` = '05001' AND z.`tipo` = 'urbana' AND c.`codigo` = '01' ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);

/* --- Corregimientos ejemplo (Medellín, zona rural) --- */
INSERT INTO `corregimiento` (`zona_id`, `codigo`, `nombre`, `estado_id`) SELECT z.`id`, v.`codigo`, v.`nombre`, 1 FROM `zona` z JOIN `municipio` m ON m.`id` = z.`municipio_id` CROSS JOIN (SELECT '01' AS codigo, 'San Sebastián de Palmitas' AS nombre UNION ALL SELECT '02' AS codigo, 'San Cristóbal' AS nombre UNION ALL SELECT '03' AS codigo, 'Altavista' AS nombre UNION ALL SELECT '04' AS codigo, 'San Antonio de Prado' AS nombre UNION ALL SELECT '05' AS codigo, 'Santa Elena' AS nombre) AS v WHERE m.`codigo` = '05001' AND z.`tipo` = 'rural' ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);

/* --- Veredas ejemplo (corregimiento Santa Elena, Medellín) --- */
INSERT INTO `vereda` (`corregimiento_id`, `codigo`, `nombre`, `estado_id`) SELECT co.`id`, v.`codigo`, v.`nombre`, 1 FROM `corregimiento` co JOIN `zona` z ON z.`id` = co.`zona_id` JOIN `municipio` m ON m.`id` = z.`municipio_id` CROSS JOIN (SELECT '01' AS codigo, 'El Plan' AS nombre UNION ALL SELECT '02', 'El Picacho' UNION ALL SELECT '03', 'La Palma') AS v WHERE m.`codigo` = '05001' AND z.`tipo` = 'rural' AND co.`codigo` = '05' ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);

SET FOREIGN_KEY_CHECKS = 1;

